  msg += '\n';
}

if (delegadas.length) {
  msg += '👥 *Combinei com outros* (' + delegadas.length + ')\n';
  delegadas.forEach(t => {
    msg += (emojiPrio[t.prioridade] || '🟡') + ' *' + t.owner + ':* ' + t.titulo + formatPrazo(t.prazo) + '\n';
  });
  msg += '\n';
}

if (jaExistiam) {
  msg += '♻️ Já existiam ' + jaExistiam + ', anotei nos cards\n\n';
}

if (!minhas.length && !delegadas.length && !jaExistiam) {
  msg += '_(nenhuma ação concreta extraída desta reunião)_\n';
}

const frontendUrl = 'https://srv2007125.hstgr.cloud';
msg += '🔗 ' + frontendUrl + '/reunioes/' + meetingId;


// Aviso de áudio longo aguardando segmentação
