const duration = meta.duration_seconds_local || 0;
const needs = duration > 3600;
return [{
  json: {
    needs_segmentation: needs,
    meeting_id: meta.meeting_id,
    duration_seconds: duration
  }
}];

// coleta as N saídas do GPT, parseia as actions de cada run, monta o prompt do juiz
const items = $input.all();
function parse(raw) {
  let p;
  if (raw.message && raw.message.content) p = typeof raw.message.content === 'string' ? JSON.parse(raw.message.content) : raw.message.content;
  else if (raw.content) p = typeof raw.content === 'string' ? JSON.parse(raw.content) : raw.content;
