const fb = { block: '' };
let data_reuniao='';try{const __ra=$('7e. Build Labeled Text').first().json.recorded_at;if(__ra){data_reuniao=new Date(__ra).toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'2-digit',year:'numeric',timeZone:'America/Sao_Paulo'});}}catch(e){}
return [{ json: {
  data_reuniao,
  summary: sa.summary || '',
  executive_summary: sa.executive_summary || '',
  labeled_text: blt.labeled_text || '',
  feedback_block: (fb && fb.block) || '',
} }];

// Junta as tarefas agregadas numa entrega só. O frontend compara com as que
