// Monta texto rotulado a partir dos segments + speaker_labels.
// Input: meeting row do SELECT (com segments e speaker_labels).
const row = $('SELECT meeting').first().json;
const segments = row.segments || [];
const labels = row.speaker_labels || {};

if (!segments.length) {
  // sem segments — usa transcrição crua como fallback
  return [{
    json: {
      meeting_id: row.id,
      user_id: row.user_id,
      recorded_at: row.recorded_at,
      source: row.source,
      meeting_type: row.meeting_type,
      labeled_text: row.transcription || '',
      duration_seconds: row.duration_seconds || 0,
    }
  }];
}

// agrupa segments contíguos do mesmo speaker em turnos
const turns = [];
for (const s of segments) {
  const last = turns[turns.length - 1];
  if (last && last.speaker === s.speaker) {
    last.text += s.text;
  } else {
    turns.push({ speaker: s.speaker, text: s.text });
  }
}

// monta texto rotulado: "Nome: texto" ou "Speaker X: texto" se não rotulado
const lines = turns.map(t => {
  const name = labels[t.speaker] || `Speaker ${t.speaker}`;
  return `${name}: ${t.text.trim()}`;
});

return [{
  json: {
    meeting_id: row.id,
    user_id: row.user_id,
    recorded_at: row.recorded_at,
    source: row.source,
    meeting_type: row.meeting_type,
    labeled_text: lines.join('\n'),
    duration_seconds: row.duration_seconds || 0,
  }
}];

